    // Младший байт  }  return result;}etl::vector<uint8_t, 256> etlVector;etl::vector<uint8_t, 256> Data = {    0xFF, 0x00, 0xAA, 0x55, 0xF0, 0x0F, 0x1E, 0x3C,    0xC3, 0x92, 0xA1, 0x50, 0x9F, 0xB4, 0xCD, 0x67,    0x5A, 0x8B, 0xED, 0x72, 0x96, 0x43, 0x1D, 0xF1,    0x3E, 0x7F, 0x8C, 0x67, 0x32, 0x44, 0x19, 0x56,    0xFF, 0x00, 0xAA, 0x55, 0xF0, 0x0F, 0x1E, 0x3C,    0xC3, 0x92, 0xA1, 0x50, 0x9F, 0xB4, 0xCD, 0x67,    0x5A, 0x8B, 0xED, 0x72, 0x96, 0x43, 0x1D, 0xF1,    0x3E, 0x7F, 0x8C, 0x67, 0x32, 0x44, 0x19, 0x56,    0xFF, 0x00, 0xAA, 0x55, 0xF0, 0x0F, 0x1E, 0x3C,    0xC3, 0x92, 0xA1, 0x50, 0x9F, 0xB4, 0xCD, 0x67,    0x5A, 0x8B, 0xED, 0x72, 0x96, 0x43, 0x1D, 0xF1,    0x3E, 0x7F, 0x8C, 0x67, 0x32, 0x44, 0x19, 0x56,    0xFF, 0x00, 0xAA, 0x55, 0xF0, 0x0F, 0x1E, 0x3C,    0xC3, 0x92, 0xA1, 0x50, 0x9F, 0xB4, 0xCD, 0x67,    0x5A, 0x8B, 0xED, 0x72, 0x96, 0x43, 0x1D, 0xF1,    0x3E, 0x7F, 0x8C, 0x67, 0x32, 0x44, 0x19, 0x56,    0xFF, 0x00, 0xAA, 0x55, 0xF0, 0x0F, 0x1E, 0x3C,    0xFF, 0x00, 0xAA, 0x55, 0xF0, 0x0F, 0x1E, 0x3C,    0xFF, 0x00, 0xAA, 0x55, 0xF0, 0x0F, 0x1E, 0x3C,};void onTimer1() {  generateTelemetryData();  etlVector = convertToETLVector(MatherBoardTelemtry);  radio.send(processorFactory.CreateRadioPacket(etlVector));}#define DIO0_PIN 7void sx1278_payload_ready_isr(uint gpio, uint32_t events) {  printf("Payload Ready Interrupt!\n");}void setup_gpio_interrupt() {  gpio_init(DIO0_PIN);  gpio_set_dir(DIO0_PIN, GPIO_IN);  gpio_pull_up(DIO0_PIN);  gpio_set_irq_enabled_with_callback(DIO0_PIN, GPIO_IRQ_EDGE_RISE, true, &sx1278_payload_ready_isr);}int main() {  if(radio.begin())    radio.setModulationFSK(9600, 4.8)        ->setTXPower(10)        ->setFrequency(SX127X::SX127X::FREQ_433)        ->setFSKConfig(PC_PACKET_FORMAT_FIXED | PC_DC_FREE_OFF | PC_CRC_ON | PC_CRC_AUTO_CLEAR_OFF)        ->disableSyncWord()        ->setPreambleLength(0);//        ->setOpMode(OPMODE_RX | OPMODE_STANDBY);  gpio_init(LED_PIN);  gpio_set_dir(LED_PIN, GPIO_OUT);  processorFactory.ChangeProcessorType(ProcessorFactory::RADIO);  processorFactory.SetupAX25("BSAT-1", "BSUGS");  setup_gpio_interrupt();//  VirtualTimer timer1(500000, onTimer1, true);//  VirtualTimer ledTimer(250000, blink, true);////  manager.addTimer(&timer1);//  manager.addTimer(&ledTimer);////  generateTelemetryData();//  etlVector = convertToETLVector(MatherBoardTelemtry);////  ledTimer.start();//  timer1.start();  etl::vector<uint8_t, 256> data;  while (true) {    data.clear();    radio.setPayloadLength(33);    data = radio.recive();    etl::vector<uint8_t, 256> DeNRZI = NRZI->ProcessDecode(data);    etl::vector<uint8_t, 256> payload = LFSR->ProcessDecode(DeNRZI);    busy_wait_ms(1);//    tight_loop_contents();  }}